import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.time.*;
import java.util.*;

public class PrintQueue {
  static final Path DATA=Paths.get("data"), STUDENTS=DATA.resolve("students.csv"), ORDERS=DATA.resolve("orders.csv"), PRINTERS=DATA.resolve("printers.csv");
  static final Scanner in=new Scanner(System.in); static final ConsoleUI ui=new ConsoleUI();
  static final Map<String,Student> students=new LinkedHashMap<>(); static final Map<String,Order> orders=new LinkedHashMap<>(); static final Queue<Order> queue=new LinkedList<>(); static final List<Printer> printers=new ArrayList<>();
  static int next=1001;
  public static void main(String[] a){ load(); ui.startup(); mainMenu(); save(); }
  static void mainMenu(){ while(true){ ui.menu("PRINTQUEUE CONTROL CENTER","Student login","Student registration","Administrator login","Live queue monitor","Exit"); switch(choice(1,5)) {case 1->studentLogin();case 2->register();case 3->adminLogin();case 4->showQueue();case 5->{ui.success("Goodbye — records saved locally.");return;} } } }
  static void register(){ui.header("STUDENT REGISTRATION");String id=ask("Student ID"),name=ask("Full name"),user=ask("Username"),pass=ask("Password"); if(id.isBlank()||name.isBlank()||user.isBlank()||pass.isBlank()){ui.error("All fields are required.");return;} if(students.values().stream().anyMatch(s->s.id.equalsIgnoreCase(id))||students.containsKey(user.toLowerCase())){ui.error("Student ID or username already exists.");return;} students.put(user.toLowerCase(),new Student(id,name,user,hash(pass)));save();ui.success("Registration complete. You can now log in.");}
  static void studentLogin(){ui.header("STUDENT LOGIN");String u=ask("Username"),p=ask("Password");Student s=students.get(u.toLowerCase());if(s==null||!s.hash.equals(hash(p))){ui.error("Invalid username or password.");return;}ui.success("Welcome, "+s.name+".");studentMenu(s);}
  static void studentMenu(Student s){while(true){ui.menu("STUDENT DASHBOARD — "+s.name,"Submit print request","My orders & queue positions","Track an order","Cancel pending order","Collect ready order","Logout");switch(choice(1,6)){case 1->submit(s);case 2->myOrders(s);case 3->track(s);case 4->cancel(s);case 5->collect(s);case 6-> {return;}}}}
  static void submit(Student s){ui.header("NEW PRINT REQUEST");String file=ask("Document filename/path");int pages=num("Pages",1),copies=num("Copies",1);String type=pick("Print type","Black & White","Color"),size=pick("Paper size","A4","A3"),mode=pick("Print mode","Single-sided","Double-sided");if(file.isBlank()){ui.error("Filename cannot be empty.");return;} Order o=new Order("PQ-"+(next++),s.id,file,pages,copies,type,size,mode); synchronized(queue){o.move(Status.PENDING,"");queue.add(o);orders.put(o.id,o);}save();ui.success(o.id+" added to the FIFO queue. Position: "+position(o));}
  static void myOrders(Student s){List<String> l=new ArrayList<>();for(Order o:orders.values())if(o.sid.equals(s.id))l.add(String.format("%-9s %-18s %-18s Queue: %s",o.id,shorten(o.file,18),o.status(),position(o)==0?"—":position(o)));ui.panel("MY PRINT REQUESTS",l.isEmpty()?List.of("No requests yet."):l);}
  static void track(Student s){String id=ask("Order ID");Order o=orders.get(id.toUpperCase());if(o==null||!o.sid.equals(s.id)){ui.error("Order not found.");return;}ui.timeline(o);}
  static void cancel(Student s){String id=ask("Order ID to cancel");Order o=orders.get(id.toUpperCase());if(o==null||!o.sid.equals(s.id)){ui.error("Order not found.");return;} synchronized(queue){if(o.status()!=Status.PENDING||!queue.remove(o)){ui.error("Only pending requests can be cancelled.");return;}o.move(Status.CANCELLED,"");}save();ui.success("Order cancelled and removed from queue.");}
  static void collect(Student s){String id=ask("Order ID to collect");Order o=orders.get(id.toUpperCase());if(o==null||!o.sid.equals(s.id)){ui.error("Order not found.");return;}if(!o.move(Status.COLLECTED,null)){ui.error("Only ready orders may be collected.");return;}save();ui.success("Document collected. Thank you!");}
  static void adminLogin(){ui.header("ADMINISTRATOR LOGIN");String u=ask("Username"),p=ask("Password");if(!u.equals("admin")||!hash(p).equals(hash("PrintQueue@2026"))){ui.error("Invalid administrator credentials.");return;}ui.success("Administrator access granted.");adminMenu();}
  static void adminMenu(){while(true){ui.menu("ADMIN CONTROL CENTER","Process next order","Queue dashboard","Printer monitor","Set printer availability","Analytics","All order history","Logout");switch(choice(1,7)){case 1->process();case 2->showQueue();case 3->showPrinters();case 4->printerStatus();case 5->analytics();case 6->allOrders();case 7->{return;}}}}
  static void process(){Order o;Printer p; synchronized(queue){o=queue.peek();p=printers.stream().filter(x->x.reserve()).findFirst().orElse(null);if(o==null){ui.warning("The print queue is empty.");return;}if(p==null){ui.warning("No printer is currently available; queue preserved.");return;}queue.remove();if(!o.move(Status.IN_PROGRESS,p.id)){p.release(false);ui.error("Order reservation failed safely.");return;}} save();ui.info("Reserved "+o.id+" on "+p.id+". Starting controlled print worker...");Thread t=new Thread(new PrintJob(o,p),"print-"+o.id);t.start();try{t.join();}catch(InterruptedException e){Thread.currentThread().interrupt();ui.error("Monitor interrupted; job continues safely.");}}
  static void showQueue(){List<String> l=new ArrayList<>();synchronized(queue){if(queue.isEmpty())l.add("Queue is empty.");else{StringBuilder b=new StringBuilder("NEXT  ");for(Order o:queue)b.append("[").append(o.id).append("] --> ");l.add(b.substring(0,Math.max(0,b.length()-5)));l.add("Queue length: "+queue.size());for(Order o:queue)l.add("  "+o.id+"  "+o.file+"  [PENDING]");}}ui.panel("LIVE FIFO PRINT QUEUE",l);}
  static void showPrinters(){List<String> l=new ArrayList<>();for(Printer p:printers)l.add(String.format("%-12s %-12s [%s]  completed: %d",p.id,p.name,p.status(),p.done()));ui.panel("PRINTER MONITOR",l);}
  static void printerStatus(){showPrinters();String id=ask("Printer ID"),state=ask("New status (AVAILABLE/OFFLINE)").toUpperCase();Printer p=printers.stream().filter(x->x.id.equalsIgnoreCase(id)).findFirst().orElse(null);try{if(p==null)throw new IllegalArgumentException("Unknown printer.");if(!p.set(PrinterStatus.valueOf(state)))throw new IllegalStateException("Busy printer cannot be taken offline.");save();ui.success("Printer status updated.");}catch(Exception e){ui.error(e.getMessage());}}
  static void analytics(){EnumMap<Status,Integer> c=new EnumMap<>(Status.class);for(Status s:Status.values())c.put(s,0);for(Order o:orders.values())c.put(o.status(),c.get(o.status())+1);long av=printers.stream().filter(p->p.status()==PrinterStatus.AVAILABLE).count(),busy=printers.stream().filter(p->p.status()==PrinterStatus.BUSY).count(),off=printers.size()-av-busy;ui.panel("SYSTEM ANALYTICS",List.of("Total orders       : "+orders.size(),"Pending            : "+c.get(Status.PENDING),"In progress        : "+c.get(Status.IN_PROGRESS),"Ready for pickup   : "+c.get(Status.READY_FOR_PICKUP),"Collected          : "+c.get(Status.COLLECTED),"Cancelled          : "+c.get(Status.CANCELLED),"Printers Available / Busy / Offline: "+av+" / "+busy+" / "+off));}
  static void allOrders(){List<String> l=new ArrayList<>();for(Order o:orders.values())l.add(o.id+" | "+o.sid+" | "+shorten(o.file,20)+" | "+o.status()+" | "+o.printer());ui.panel("ALL ORDER HISTORY",l.isEmpty()?List.of("No orders recorded."):l);}
  static int choice(int a,int b){while(true){try{int x=Integer.parseInt(in.nextLine().trim());if(x>=a&&x<=b)return x;}catch(Exception e){}ui.error("Enter a number from "+a+" to "+b+".");System.out.print("  Select option: ");}}
  static int num(String label,int min){while(true){try{System.out.print("  "+label+": ");int n=Integer.parseInt(in.nextLine().trim());if(n>=min)return n;}catch(Exception e){}ui.error(label+" must be a positive whole number.");}}
  static String ask(String s){System.out.print("  "+s+": ");return in.nextLine().trim();} static String pick(String label,String a,String b){while(true){System.out.print("  "+label+" [1] "+a+" [2] "+b+": ");String x=in.nextLine().trim();if(x.equals("1"))return a;if(x.equals("2"))return b;ui.error("Choose 1 or 2.");}}
  static int position(Order wanted){synchronized(queue){int n=1;for(Order o:queue){if(o==wanted)return n;n++;}}return 0;}
  static String shorten(String s,int n){return s.length()>n?s.substring(0,n-1)+"…":s;}
  static String hash(String s){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8));StringBuilder b=new StringBuilder();for(byte x:d)b.append(String.format("%02x",x));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}}
  static String enc(String s){return Base64.getEncoder().encodeToString(s.getBytes(StandardCharsets.UTF_8));}static String dec(String s){return new String(Base64.getDecoder().decode(s),StandardCharsets.UTF_8);}
  static synchronized void save(){try{Files.createDirectories(DATA);List<String> a=new ArrayList<>();for(Student s:students.values())a.add(enc(s.id)+","+enc(s.name)+","+enc(s.user)+","+s.hash);Files.write(STUDENTS,a);a.clear();for(Order o:orders.values())a.add(String.join(",",enc(o.id),enc(o.sid),enc(o.file),""+o.pages,""+o.copies,enc(o.type),enc(o.size),enc(o.mode),enc(o.date),o.status().name(),enc(o.printer()),enc(o.history())));Files.write(ORDERS,a);a.clear();for(Printer p:printers)a.add(enc(p.id)+","+enc(p.name)+","+p.status()+","+p.done());Files.write(PRINTERS,a);}catch(IOException e){ui.error("Could not save records: "+e.getMessage());}}
  static void load(){try{Files.createDirectories(DATA);if(Files.exists(STUDENTS))for(String z:Files.readAllLines(STUDENTS)){String[] x=z.split(",",-1);if(x.length==4)students.put(dec(x[2]).toLowerCase(),new Student(dec(x[0]),dec(x[1]),dec(x[2]),x[3]));}if(Files.exists(ORDERS))for(String z:Files.readAllLines(ORDERS)){String[] x=z.split(",",-1);if(x.length==12){Order o=new Order(dec(x[0]),dec(x[1]),dec(x[2]),Integer.parseInt(x[3]),Integer.parseInt(x[4]),dec(x[5]),dec(x[6]),dec(x[7]),dec(x[8]),Status.valueOf(x[9]),dec(x[10]),dec(x[11]));orders.put(o.id,o);if(o.status()==Status.PENDING)queue.add(o);next=Math.max(next,Integer.parseInt(o.id.substring(3))+1);}}if(Files.exists(PRINTERS))for(String z:Files.readAllLines(PRINTERS)){String[] x=z.split(",",-1);if(x.length==4)printers.add(new Printer(dec(x[0]),dec(x[1]),PrinterStatus.valueOf(x[2]),Integer.parseInt(x[3])));}if(printers.isEmpty()){printers.add(new Printer("PRINTER-01","Library Laser",PrinterStatus.AVAILABLE,0));printers.add(new Printer("PRINTER-02","Campus Color",PrinterStatus.AVAILABLE,0));}}catch(Exception e){System.out.println("Data load warning: "+e.getMessage());}}
  enum Status{SUBMITTED,PENDING,IN_PROGRESS,READY_FOR_PICKUP,COLLECTED,CANCELLED} enum PrinterStatus{AVAILABLE,BUSY,OFFLINE}
  static class Student{final String id,name,user,hash;Student(String a,String b,String c,String d){id=a;name=b;user=c;hash=d;}}
  static class Order{final String id,sid,file,type,size,mode,date;final int pages,copies;private Status stat;private String assigned;private final List<String> history=new ArrayList<>();Order(String id,String sid,String f,int p,int c,String t,String sz,String m){this(id,sid,f,p,c,t,sz,m,LocalDateTime.now().toString(),Status.SUBMITTED,"","");}Order(String id,String sid,String f,int p,int c,String t,String sz,String m,String d,Status st,String pr,String h){this.id=id;this.sid=sid;file=f;pages=p;copies=c;type=t;size=sz;mode=m;date=d;stat=st;assigned=pr;if(h.isBlank())history.add(st+" @ "+d);else history.addAll(Arrays.asList(h.split("\\|")));}synchronized Status status(){return stat;}synchronized String printer(){return assigned;}synchronized String history(){return String.join("|",history);}synchronized boolean move(Status n,String p){boolean ok=(stat==Status.SUBMITTED&&n==Status.PENDING)||(stat==Status.PENDING&&(n==Status.IN_PROGRESS||n==Status.CANCELLED))||(stat==Status.IN_PROGRESS&&n==Status.READY_FOR_PICKUP)||(stat==Status.READY_FOR_PICKUP&&n==Status.COLLECTED);if(!ok)return false;stat=n;if(p!=null)assigned=p;history.add(n+" @ "+LocalDateTime.now());return true;}}
  static class Printer{final String id,name;private PrinterStatus stat;private int completed;Printer(String i,String n,PrinterStatus s,int c){id=i;name=n;stat=s;completed=c;}synchronized PrinterStatus status(){return stat;}synchronized boolean reserve(){if(stat!=PrinterStatus.AVAILABLE)return false;stat=PrinterStatus.BUSY;return true;}synchronized void release(boolean ok){if(ok)completed++;if(stat==PrinterStatus.BUSY)stat=PrinterStatus.AVAILABLE;}synchronized boolean set(PrinterStatus n){if(stat==PrinterStatus.BUSY)return false;stat=n;return true;}synchronized int done(){return completed;}}
  static class PrintJob implements Runnable{final Order o;final Printer p;PrintJob(Order a,Printer b){o=a;p=b;}public void run(){boolean ok=false;try{int total=Math.max(1,o.pages*o.copies);for(int i=0;i<=total;i++){ui.progress(o,p,i*100/total,i,total);Thread.sleep(Boolean.getBoolean("printqueue.noAnimation")?1:180);}if(!o.move(Status.READY_FOR_PICKUP,null))throw new IllegalStateException("Invalid completion transition");ok=true;ui.success(o.id+" is ready for pickup.");}catch(InterruptedException e){Thread.currentThread().interrupt();ui.error("Print simulation interrupted; job retained as in progress.");}finally{p.release(ok);save();}}}
  static class UI{final boolean ansi=!Boolean.getBoolean("printqueue.noColor");String c(String x,String v){return ansi?x+v+"\u001B[0m":v;}void header(String s){System.out.println(c("\u001B[36m","\n╔════════════════════════════════════════════════════════════════════╗\n║ "+pad(s,64)+" ║\n╚════════════════════════════════════════════════════════════════════╝"));}void panel(String s,List<String> l){header(s);for(String x:l)System.out.println("  "+x);System.out.println();}void menu(String s,String...o){header(s);for(int i=0;i<o.length;i++)System.out.println(c("\u001B[35m","  ["+(i+1)+"]")+" "+o[i]);System.out.print("\n  Select option: ");}void success(String s){System.out.println(c("\u001B[32m","[SUCCESS] ")+s);}void error(String s){System.out.println(c("\u001B[31m","[ERROR] ")+s);}void info(String s){System.out.println(c("\u001B[34m","[INFO] ")+s);}void warning(String s){System.out.println(c("\u001B[33m","[WARNING] ")+s);}void startup(){header("PRINTQUEUE — SMART CAMPUS PRINTING");for(int i=0;i<=100;i+=25){System.out.print("  Initializing: ["+"█".repeat(i/5)+"░".repeat(20-i/5)+"] "+i+"%\r");try{Thread.sleep(System.console()==null?0:110);}catch(InterruptedException e){Thread.currentThread().interrupt();}}System.out.println();success("System ready.");}void progress(Order o,Printer p,int pct,int done,int total){System.out.println("\r  Printing "+o.id+" on "+p.id+"  ["+"#".repeat(pct/5)+"-".repeat(20-pct/5)+"] "+pct+"%  pages "+done+"/"+total+"       ");}void timeline(Order o){header("ORDER TRACKING — "+o.id);for(Status s:Status.values()){if(s==Status.CANCELLED)continue;String q=o.status()==Status.CANCELLED?(s==Status.CANCELLED?">":" "):(s.ordinal()<o.status().ordinal()?"✓":s==o.status()?">":" ");System.out.println("  ["+q+"] "+s);}if(o.status()==Status.CANCELLED)System.out.println("  [!] CANCELLED");System.out.println("\n  Current status: "+o.status()+"\n  Printer: "+(o.printer().isBlank()?"Not assigned":o.printer()));}static String pad(String s,int n){return s.length()>n?s.substring(0,n):s+" ".repeat(n-s.length());}}
}


